import React, { useState, useEffect } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

const Graph = () => {
    const [data, setData] = useState([]); // Estado para almacenar los datos de la API
    const [loading, setLoading] = useState(true); // Estado para manejar la carga

    // Función para obtener el valor del dólar
    const fetchDollarValue = async () => {
        try {
            const response = await fetch('https://api.yourservice.com/fetch-one?from=USD&to=MXN', {
                headers: {
                    'Authorization': 'Bearer 7487e94f8f-82434b0371-skncut' // Asegúrate de usar el encabezado correcto para tu API
                }
            });
            const result = await response.json();
            const dollarValue = result.value; // Ajusta esto según la estructura de la respuesta de tu API

            // Agregar el valor del dólar a los datos
            setData(prevData => [
                ...prevData,
                { name: new Date().toLocaleTimeString(), value: dollarValue } // Agregar la hora actual y el valor
            ]);
            setLoading(false);
        } catch (error) {
            console.error('Error fetching dollar value:', error);
        }
    };

    useEffect(() => {
        fetchDollarValue(); // Llamar a la API al cargar el componente

        // Configurar un intervalo para actualizar cada 10 segundos
        const intervalId = setInterval(() => {
            fetchDollarValue();
        }, 10000); // 10 segundos

        // Limpiar el intervalo al desmontar el componente
        return () => clearInterval(intervalId);
    }, []);

    return (
        <ResponsiveContainer width="100%" height={300}>
            {loading ? (
                <div>Cargando...</div> // Mensaje de carga
            ) : (
                <LineChart data={data}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="name" label={{ value: 'Hora', position: 'insideBottomRight', offset: 0 }} />
                    <YAxis label={{ value: 'Valor del Dólar', angle: -90, position: 'insideLeft' }} />
                    <Tooltip />
                    <Legend />
                    <Line type="monotone" dataKey="value" stroke="#8884d8" />
                </LineChart>
            )}
        </ResponsiveContainer>
    );
};

export default Graph;
